<script lang="ts">
  /* eslint-disable svelte/no-at-html-tags -- egg hatch body from legacy creature modal builder */
  import { onDestroy } from 'svelte';
  import { setShow, setClose } from '../bridge/eggHatchModalBridge.js';

  type HatchPhase = 'egg' | 'crack' | 'burst' | 'reveal';

  const CRACK_AT_MS = 800;
  const BURST_AT_MS = 1800;
  const REVEAL_AT_MS = 2100;

  let visible = $state(false);
  let contentHtml = $state('');
  let contentClass = $state('');
  let eggSpriteUrl = $state('img/common-egg.png');
  let phase = $state<HatchPhase>('egg');

  let timerCrack: ReturnType<typeof setTimeout> | null = null;
  let timerBurst: ReturnType<typeof setTimeout> | null = null;
  let timerReveal: ReturnType<typeof setTimeout> | null = null;
  let modalSkipHandler: ((e: MouseEvent) => void) | null = null;
  let keySkipHandler: ((e: KeyboardEvent) => void) | null = null;
  let keyRevealCloseHandler: ((e: KeyboardEvent) => void) | null = null;

  function clearIntroTimers() {
    if (timerCrack) clearTimeout(timerCrack);
    if (timerBurst) clearTimeout(timerBurst);
    if (timerReveal) clearTimeout(timerReveal);
    timerCrack = null;
    timerBurst = null;
    timerReveal = null;
  }

  function detachSkipListeners() {
    const modal = document.getElementById('eggHatchModal');
    if (modal && modalSkipHandler) {
      modal.removeEventListener('click', modalSkipHandler, true);
    }
    if (keySkipHandler) {
      document.removeEventListener('keydown', keySkipHandler, true);
    }
    modalSkipHandler = null;
    keySkipHandler = null;
  }

  function detachRevealKeyListener() {
    if (keyRevealCloseHandler) {
      document.removeEventListener('keydown', keyRevealCloseHandler, true);
    }
    keyRevealCloseHandler = null;
  }

  function attachRevealKeyListener() {
    detachRevealKeyListener();
    keyRevealCloseHandler = (e: KeyboardEvent) => {
      if (phase !== 'reveal') return;
      if (e.key === 'Escape') {
        e.preventDefault();
        close();
      }
    };
    document.addEventListener('keydown', keyRevealCloseHandler, true);
  }

  function skipIntro() {
    if (phase === 'reveal') return;
    clearIntroTimers();
    phase = 'reveal';
    detachSkipListeners();
    attachRevealKeyListener();
  }

  function attachSkipListeners() {
    detachSkipListeners();
    const modal = document.getElementById('eggHatchModal');
    modalSkipHandler = (e: MouseEvent) => {
      if (phase === 'reveal') return;
      if (e.target === modal) {
        e.preventDefault();
        e.stopPropagation();
        skipIntro();
      }
    };
    keySkipHandler = (e: KeyboardEvent) => {
      if (phase === 'reveal') return;
      if (e.key === 'Escape' || e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        skipIntro();
      }
    };
    modal?.addEventListener('click', modalSkipHandler, true);
    document.addEventListener('keydown', keySkipHandler, true);
  }

  function scheduleIntroSequence() {
    clearIntroTimers();
    phase = 'egg';
    timerCrack = setTimeout(() => {
      if (phase === 'egg') phase = 'crack';
    }, CRACK_AT_MS);
    timerBurst = setTimeout(() => {
      if (phase === 'egg' || phase === 'crack') phase = 'burst';
    }, BURST_AT_MS);
    timerReveal = setTimeout(() => {
      phase = 'reveal';
      detachSkipListeners();
      attachRevealKeyListener();
    }, REVEAL_AT_MS);
    attachSkipListeners();
  }

  function show(html: string, options?: Record<string, unknown>) {
    contentHtml = html;
    contentClass = options?.contentClass ? String(options.contentClass) : '';
    const rarity = options?.rarity ? String(options.rarity) : 'common';
    eggSpriteUrl = `img/${rarity}-egg.png`;
    visible = true;
    document.getElementById('eggHatchModal')?.classList.add('show');
    scheduleIntroSequence();
  }

  function close() {
    clearIntroTimers();
    detachSkipListeners();
    detachRevealKeyListener();
    visible = false;
    contentHtml = '';
    contentClass = '';
    phase = 'egg';
    document.getElementById('eggHatchModal')?.classList.remove('show');
  }

  setShow(show);
  setClose(close);
  onDestroy(() => {
    clearIntroTimers();
    detachSkipListeners();
    detachRevealKeyListener();
    setShow(() => {});
    setClose(() => {});
  });
</script>

<!-- svelte-ignore a11y_click_events_have_key_events -->
<!-- svelte-ignore a11y_no_static_element_interactions -->
<div
  class="stats-content {contentClass}"
  class:egg-hatch-revealed={phase === 'reveal'}
  id="eggHatchContent"
  data-action="stopPropagation"
  data-action-stop
>
  {#if visible && phase !== 'reveal'}
    <div
      class="egg-hatch-intro"
      class:egg-hatch-burst={phase === 'burst'}
      role="presentation"
      onclick={() => skipIntro()}
    >
      <div class="egg-hatch-particles" aria-hidden="true">
        <span class="egg-particle"></span><span class="egg-particle"></span>
        <span class="egg-particle"></span><span class="egg-particle"></span>
        <span class="egg-particle"></span><span class="egg-particle"></span>
        <span class="egg-particle"></span><span class="egg-particle"></span>
      </div>
      <div
        class="egg-hatch-egg-stage"
        class:egg-crack-1={phase === 'crack' || phase === 'burst'}
        class:egg-crack-3={phase === 'burst'}
      >
        <img src={eggSpriteUrl} alt="" class="egg-hatch-egg-sprite" />
        <span class="egg-crack-line egg-crack-a" aria-hidden="true"></span>
        <span class="egg-crack-line egg-crack-b" aria-hidden="true"></span>
        <span class="egg-crack-line egg-crack-c" aria-hidden="true"></span>
      </div>
    </div>
  {/if}
  {#if visible && contentHtml}
    <div class="egg-hatch-creature-panel" class:visible={phase === 'reveal'}>
      {@html contentHtml}
    </div>
  {/if}
</div>
